const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definition
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.inList('ADM0_NAME', ['Namibia', 'Botswana', 'Lesotho']));

  const geometry = countries.geometry().dissolve({maxError: 100}); // Dissolve into a single geometry

  // Check if geometry is valid
  if (geometry.area().getInfo() === 0) {
    console.log("Error: Geometry for specified countries is invalid or empty.");
    console.log("C3"); // Calculation Failure due to invalid geometry
    return;
  }

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Define scale for reduceRegion operations
  const scale = 5000; // CHIRPS resolution is ~5.5km, use 5km scale.

  // Function to calculate total rainfall for Dec-Jan for a given start year
  const calculateDecJanRain = (year) => {
    const startDate = ee.Date.fromYMD(year, 12, 1);
    const endDate = ee.Date.fromYMD(year + 1, 1, 31); // Jan 31 of next year

    const rainfallCollection = chirps
      .filterDate(startDate, endDate)
      .filterBounds(geometry);

    // Check for empty collection
    if (rainfallCollection.size().getInfo() === 0) {
      return null; // Return null if no images found
    }

    // Sum all daily rainfall images in the collection
    const totalRainfall = rainfallCollection.sum();

    return totalRainfall;
  };

  // 3. Calculate rainfall for the comparison period (Dec 2018 - Jan 2019)
  const comparisonRainfallImage = calculateDecJanRain(2018);

  // Check for C1 (Empty Collection) for comparison period
  if (comparisonRainfallImage === null) {
    console.log("C1: No CHIRPS data found for Dec 2018 - Jan 2019.");
    return;
  }

  const comparisonRainfallResult = await comparisonRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Check for C3 (Calculation Failure) for comparison period
  if (comparisonRainfallResult === null || isNaN(comparisonRainfallResult)) {
    console.log("C3: Failed to calculate mean rainfall for Dec 2018 - Jan 2019 (result is null/NaN).");
    return;
  }

  // Calculate pixel count for validation
  const comparisonPixelCount = await comparisonRainfallImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Check for C2 (No Valid Pixels) for comparison period
  if (comparisonPixelCount === 0) {
    console.log("C2: No valid pixels for Dec 2018 - Jan 2019 after masking/filtering.");
    return;
  }
  console.log(`2018/19 Rain (mm): ${comparisonRainfallResult.toFixed(2)} (Pixels: ${comparisonPixelCount})`);


  // 4. Calculate long-term average rainfall (Dec-Jan for 2000-2019)
  const annualRainfallSums = [];
  let successfulYears = 0;

  for (let year = 2000; year <= 2019; year++) {
    const currentYearRainfallImage = calculateDecJanRain(year);

    if (currentYearRainfallImage === null) {
      console.log(`Skipping year ${year} due to empty collection.`);
      continue;
    }

    const yearRainfallResult = await currentYearRainfallImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    const yearPixelCount = await currentYearRainfallImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).get('precipitation').getInfo();


    if (yearRainfallResult !== null && !isNaN(yearRainfallResult) && yearPixelCount > 0) {
      annualRainfallSums.push(yearRainfallResult);
      successfulYears++;
    } else {
        console.log(`Skipping year ${year} due to null/NaN result or zero pixels (${yearPixelCount}).`);
    }
  }

  if (successfulYears === 0) {
    console.log("C1: No valid rainfall data found for any year in the long-term average period (2000-2019).");
    return;
  }

  const longTermAverage = annualRainfallSums.reduce((a, b) => a + b, 0) / annualRainfallSums.length;

  // Check for C3 (Calculation Failure) for long-term average
  if (longTermAverage === null || isNaN(longTermAverage)) {
    console.log("C3: Failed to calculate long-term average rainfall (result is null/NaN).");
    return;
  }
  console.log(`Long-term Avg Rain (mm, ${successfulYears} years): ${longTermAverage.toFixed(2)}`);

  // 5. Comparison and Final Answer
  if (comparisonRainfallResult < longTermAverage) {
    console.log("A"); // Yes, received less rain
  } else {
    console.log("B"); // No, did not receive less rain
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

